import { loadFont as loadGilda } from "@remotion/google-fonts/GildaDisplay";
import { loadFont as loadAlbert } from "@remotion/google-fonts/AlbertSans";
import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// GB HOUSE & CO · v2 do vídeo no modelo da referência (reel da Frame Coletivo, 59 s). O cliente recusou o v1 (cores da GB e
// cenas próprias) e pediu "exatamente igual": mesma narrativa, mesmas cenas e transições, as CORES DA REFERÊNCIA, só o logo
// principal, a foto da sala no lugar da cerveja, 25% no lugar do preço e nenhum valor em reais.
// Cada cena ocupa o mesmo intervalo da referência (tempos abaixo = tempos do vídeo, iguais aos da referência). A voz (Marcos Alves,
// três partes) é recortada frase por frase e cada frase entra no segundo em que a frase equivalente entra na referência
// ((arquivo do cliente)). Os 5 s sem fala do meio (27–32,6 s) também são da referência.
// v3 (19/10): voz trocada pela o locutor, gravada em 6 blocos corridos (src/voz-ref-v3/), cada bloco no início do trecho falado
// da referência; música de fundo do o diretor (BIA - We On Go, instrumental).
// Cores medidas nos quadros da referência: limão #D9F903, branco, verde-escuro da pincelada, magenta do marca-texto,
// amostras em preto e vermelho, verde-garrafa, papel com amarelo, azul-petróleo com ciano.

const { fontFamily: SERIF } = loadGilda("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadAlbert("normal", { weights: ["400", "500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: COND } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });

export const GBR2_FPS = 30;
export const GBR2_FRAMES = Math.round(59.2 * GBR2_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

// cores da referência
const LIME = "#D9F903";
const LIME_D = "#C6E602";
const WHITE = "#FDFDFD";
const INK = "#1D2A12";            // texto escuro sobre o limão
const BRUSH = "#1F3A17";          // pincelada e selo
const MAGENTA = "#E24AA8";
const FLAG = "#C8102E";
const DARK = "#141414";
const RED = "#E3261E";
const BOTTLE = "#0A2A1E";
const MINT = "#3EE6A0";
const PAPER = "#E9E5DC";
const YELLOW = "#F5D21C";
const TEAL = "#0B1A20";
const CYAN = "#2CC0EA";

// troca de cena (tempos do vídeo = tempos da referência)
const CUT = { B: 3.3, C: 7.3, D: 10.75, E: 15.0, F: 18.0, G: 22.0, H: 26.0, I: 28.2, J: 32.7, K: 35.1, L: 37.4, M: 43.6, N: 48.4, O: 54.85 };

// ───────── peças comuns ─────────
const blurIn = (t: number, at: number, d = 0.35): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: Math.min(1, e * 1.8), filter: `blur(${((1 - e) * 10).toFixed(1)}px)`, transform: `translateY(${((1 - e) * 10).toFixed(1)}px)` };
};
type W = [string, number];
// palavras que entram uma a uma; as marcadas ganham a faixa de marca-texto passando por baixo (metade de baixo, como na referência)
const Words: React.FC<{ t: number; ws: W[]; size: number; color: string; font?: string; weight?: number; gap?: number; mark?: number[]; markColor?: string; markAt?: number; ls?: string; markText?: string }> = ({ t, ws, size, color, font = SERIF, weight = 400, gap = 0.24, mark = [], markColor = LIME, markAt, ls = "-0.025em", markText }) => (
  <div style={{ display: "flex", justifyContent: "center", gap: size * gap, whiteSpace: "nowrap" }}>
    {ws.map(([w, at], i) => {
      const m = mark.includes(i);
      const a0 = markAt ?? at + 0.1;
      const sw = m ? io(t, a0, a0 + 0.3) : 0;
      return (
        <span key={i} style={{ position: "relative", display: "inline-block", fontFamily: font, fontWeight: weight, fontSize: size, lineHeight: 1.06, letterSpacing: ls, color: m && markText ? markText : color, ...blurIn(t, at) }}>
          {m ? <span style={{ position: "absolute", left: -size * 0.05, right: -size * 0.05, top: "48%", bottom: "4%", background: markColor, transformOrigin: "left center", transform: `scaleX(${sw.toFixed(3)})`, zIndex: 0 }} /> : null}
          <span style={{ position: "relative", zIndex: 1 }}>{w}</span>
        </span>
      );
    })}
  </div>
);
const Caps: React.FC<{ children: React.ReactNode; size?: number; color?: string; ls?: string; weight?: number; style?: React.CSSProperties }> = ({ children, size = 22, color = INK, ls = "0.24em", weight = 700, style }) => (
  <div style={{ fontFamily: SANS, fontWeight: weight, fontSize: size, letterSpacing: ls, textTransform: "uppercase", color, whiteSpace: "nowrap", ...style }}>{children}</div>
);
// número do capítulo gigante e apagado no rodapé
const BigNum: React.FC<{ n: string; c: string; t: number; at: number; font?: string }> = ({ n, c, t, at, font = SERIF }) => (
  <div style={{ position: "absolute", left: 40, bottom: -70, fontFamily: font, fontSize: 520, lineHeight: 1, letterSpacing: "-0.04em", color: c, transform: `translateY(${((1 - k(t, at, 0.8)) * 90).toFixed(1)}px)` }}>{n}</div>
);
// rótulo do topo "RESERVA 0X ······ GB HOUSE & CO" (na referência: "BURACO 0X ······ FRAME COLETIVO")
const TopLabel: React.FC<{ n: string; t: number; at: number; c?: string }> = ({ n, t, at, c = "rgba(29,42,18,0.55)" }) => {
  const e = k(t, at, 0.6);
  return (
    <div style={{ position: "absolute", left: 90, right: 90, top: 300, display: "flex", alignItems: "center", gap: 18, opacity: e }}>
      <Caps size={17} color={c} ls="0.3em">Reserva {n}</Caps>
      <div style={{ flex: 1, borderTop: `2px dotted ${c}`, transformOrigin: "left", transform: `scaleX(${e.toFixed(3)})` }} />
      <Caps size={17} color={c} ls="0.3em">GB House &amp; Co</Caps>
    </div>
  );
};
// granulado / meio-tom
const Grain: React.FC<{ seed: number; o?: number; blend?: React.CSSProperties["mixBlendMode"] }> = ({ seed, o = 0.08, blend = "overlay" }) => (
  <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: blend, opacity: o }}>
    <svg width="1080" height="1920"><filter id={`gr${seed}`}><feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="2" seed={seed} /></filter><rect width="1080" height="1920" filter={`url(#gr${seed})`} /></svg>
  </AbsoluteFill>
);
// vazamentos de luz nas bordas (cenas brancas da referência)
const Leak: React.FC<{ t: number; c?: string; side?: "lr" | "top" | "bottom" }> = ({ t, c = LIME, side = "lr" }) => {
  const w = 0.5 + 0.5 * Math.sin(t * 2.3);
  if (side === "top") return <AbsoluteFill style={{ pointerEvents: "none", background: `linear-gradient(180deg, rgba(255,255,255,${(0.85 * w).toFixed(2)}) 0%, rgba(255,255,255,0) 22%)` }} />;
  if (side === "bottom") return <AbsoluteFill style={{ pointerEvents: "none", background: `linear-gradient(0deg, ${c} 0%, rgba(217,249,3,0) ${(26 + 8 * w).toFixed(0)}%)` }} />;
  return <AbsoluteFill style={{ pointerEvents: "none", background: `linear-gradient(90deg, ${c} 0%, rgba(217,249,3,0) ${(6 + 4 * w).toFixed(1)}%, rgba(217,249,3,0) ${(94 - 4 * w).toFixed(1)}%, ${c} 100%)`, opacity: 0.9 }} />;
};
const Vignette: React.FC<{ s?: number }> = ({ s = 0.6 }) => <AbsoluteFill style={{ pointerEvents: "none", background: `radial-gradient(ellipse at 50% 42%, rgba(0,0,0,0) 45%, rgba(0,0,0,${s}) 100%)` }} />;

const sv = (s: number, c: string, ch: React.ReactNode, sw = 1.7) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
type Ic = (s: number, c: string) => React.ReactNode;
const IcoChat: Ic = (s, c) => sv(s, c, <path d="M4 6.5A2.5 2.5 0 016.5 4h11A2.5 2.5 0 0120 6.5v7a2.5 2.5 0 01-2.5 2.5H11l-4.5 3.5V16A2.5 2.5 0 014 13.5z" />);
const IcoKey: Ic = (s, c) => sv(s, c, <><circle cx="8" cy="15.5" r="4" /><path d="M11 12.7L19.5 4.2M16 7.7l2.3 2.3M13.5 10.2l1.8 1.8" /></>);
const IcoBed: Ic = (s, c) => sv(s, c, <path d="M3 18V7M3 14h18v4M21 14v-2a3 3 0 00-3-3h-7v5M6.5 11.5a1.5 1.5 0 100-.01" />);
const IcoStar: Ic = (s, c) => sv(s, c, <path d="M12 3.5l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 16.9l-5.2 2.7 1-5.8L3.5 9.7l5.9-.9z" />);
const IcoCheck: Ic = (s, c) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />, 2.4);
const IcoDoor: Ic = (s, c) => sv(s, c, <><path d="M6 20V4.5A1.5 1.5 0 017.5 3h9A1.5 1.5 0 0118 4.5V20M4 20h16" /><circle cx="14.5" cy="12" r="0.9" fill={c} /></>);

// ───────── A · 0–3,3 · gancho (limão) ─────────
const SA: React.FC<{ t: number }> = ({ t }) => {
  const brush = io(t, 1.25, 1.55);
  const exit = io(t, 2.65, 3.3);                       // pincelada e palavra saem para a esquerda, como na referência
  return (
    <AbsoluteFill style={{ background: `radial-gradient(ellipse at 50% 45%, ${LIME} 0%, ${LIME_D} 100%)` }}>
      <BigNum n="01" c="rgba(29,42,18,0.07)" t={t} at={-0.3} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 800, transform: `translateX(${(-exit * 1300).toFixed(1)}px)` }}>
        <Words t={t} size={58} color={INK} ws={[["o", 0.22], ["seu", 0.38], ["imóvel", 0.56], ["merece", 1.12]]} gap={0.22} />
      </div>
      <div style={{ position: "absolute", left: 40, right: 40, top: 880, height: 220, transform: `translateX(${(-exit * 1400).toFixed(1)}px)` }}>
        <svg width={1000} height={220} viewBox="0 0 1000 220" style={{ position: "absolute", inset: 0, overflow: "visible", transform: "scaleY(1.25)" }}>
          <defs><clipPath id="brR"><rect x={0} y={-40} width={1100 * brush} height={300} /></clipPath></defs>
          <g clipPath="url(#brR)">
            <path d="M20 108c30-40 140-62 300-66 190-4 380 6 560-4 50-3 90 0 110 8-8 16-30 26-22 44 8 18 36 26 26 44-70 18-220 12-380 14-200 2-390 14-540 10C50 170 6 150 4 132c-2-10 6-16 16-24z" fill={BRUSH} />
            <path d="M940 96c30 2 50 10 60 22M30 160c120 14 300 10 470 6" stroke={BRUSH} strokeWidth={10} strokeLinecap="round" fill="none" opacity={0.85} />
            <path d="M60 80c160-18 360-20 560-14M100 140c220 8 460 2 700-6" stroke="#2E5222" strokeWidth={3} fill="none" opacity={0.7} />
          </g>
        </svg>
        <div style={{ position: "absolute", left: 0, right: 0, top: 22, display: "flex", justifyContent: "center", fontFamily: SERIF, fontSize: 170, lineHeight: 1, letterSpacing: "-0.04em", color: LIME, ...blurIn(t, 1.44, 0.3) }}>atenção</div>
      </div>
      <Grain seed={11} o={0.1} />
    </AbsoluteFill>
  );
};

// selo de tampinha (o "fc" da referência)
const Seal: React.FC<{ s: number; t: number }> = ({ s, t }) => {
  const n = 22;
  const pts = Array.from({ length: n * 2 }, (_, i) => { const a = (i / (n * 2)) * Math.PI * 2; const r = i % 2 ? s * 0.47 : s * 0.5; return `${(s / 2 + Math.cos(a) * r).toFixed(1)},${(s / 2 + Math.sin(a) * r).toFixed(1)}`; }).join(" ");
  return (
    <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`} style={{ transform: `rotate(${(t * 18).toFixed(1)}deg)`, filter: "drop-shadow(0 10px 16px rgba(0,0,0,0.25))" }}>
      <polygon points={pts} fill={BRUSH} />
      <circle cx={s / 2} cy={s / 2} r={s * 0.38} fill="none" stroke="rgba(217,249,3,0.35)" strokeWidth={2} />
      <text x={s / 2} y={s / 2 + s * 0.12} textAnchor="middle" fontFamily={SERIF} fontStyle="italic" fontSize={s * 0.36} fill={WHITE} transform={`rotate(${(-t * 18).toFixed(1)} ${s / 2} ${s / 2})`}>gb</text>
    </svg>
  );
};

// ───────── B · 3,3–7,3 · somos a GB (branco) ─────────
const SB: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: WHITE }}>
    <BigNum n="02" c="rgba(0,0,0,0.04)" t={t} at={CUT.B} />
    <div style={{ position: "absolute", left: 0, right: 0, top: 690, display: "flex", justifyContent: "center", ...blurIn(t, 3.3) }}><div style={{ fontFamily: SERIF, fontSize: 30, color: "#555" }}>somos a</div></div>
    <div style={{ position: "absolute", left: 540 - 70, top: 750, transform: `scale(${pop(t, 3.3, 0.45).toFixed(4)})` }}><Seal s={140} t={t} /></div>
    <div style={{ position: "absolute", left: 0, right: 0, top: 920 }}>
      <Words t={t} size={118} color="#111" ws={[["GB", 3.44], ["House", 3.82], ["&", 4.16], ["Co.", 4.28]]} gap={0.2} mark={[0, 1, 2, 3]} markColor={LIME} markAt={3.5} />
    </div>
    <div style={{ position: "absolute", left: 0, right: 0, top: 1080, display: "flex", justifyContent: "center", gap: 12, ...blurIn(t, 4.6) }}>
      <Caps size={16} color="#666" ls="0.32em">Private Hospitality &amp; Property Services</Caps><Caps size={16} color="#666" ls="0">·</Caps>
      <div style={{ marginTop: -4 }}>{IcoKey(22, "#666")}</div>
    </div>
    <Leak t={t} />
    <Grain seed={12} o={0.05} />
  </AbsoluteFill>
);

// ───────── C · 7,3–10,75 · 25% (limão) ─────────
const SC: React.FC<{ t: number }> = ({ t }) => {
  const p = io(t, 8.0, 8.85);
  const v = Math.round(p * 25);
  return (
    <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 46%, #E4FB45 0%, ${LIME} 38%, ${LIME_D} 100%)`, transform: `scale(${(1 + 0.04 * lin(t, 7.3, 10.75)).toFixed(4)})` }}>
      <BigNum n="03" c="rgba(29,42,18,0.07)" t={t} at={CUT.C} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 820 }}>
        <Words t={t} size={60} color={INK} ws={[["gestão", 7.45], ["completa", 7.7], ["por", 7.95]]} gap={0.22} />
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 910, display: "flex", justifyContent: "center", alignItems: "flex-start", ...blurIn(t, 8.0, 0.3) }}>
        <div style={{ fontFamily: SERIF, fontSize: 260, lineHeight: 1, color: "#111", letterSpacing: "-0.05em", fontVariantNumeric: "tabular-nums", filter: `blur(${(p > 0.02 && p < 0.98 ? 4 : 0).toFixed(1)}px)`, transform: `scale(${(1 + 0.05 * bump(t, 8.85, 0.45)).toFixed(4)})` }}>{v}</div>
        <div style={{ fontFamily: SERIF, fontSize: 130, color: "#111", marginTop: 40, letterSpacing: "-0.03em" }}>%</div>
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1210, display: "flex", justifyContent: "center", ...blurIn(t, 9.1) }}>
        <Caps size={20} color="rgba(29,42,18,0.6)" ls="0.3em">sobre as reservas · concierge</Caps>
      </div>
      <Grain seed={13} o={0.1} />
    </AbsoluteFill>
  );
};

// ───────── D · 10,75–15 · do que o seu imóvel precisa? o gramado com a bandeira (limão) ─────────
const Green: React.FC<{ t: number }> = ({ t }) => {
  const rise = k(t, 10.85, 0.7);
  const ball = io(t, 11.8, 12.6);
  const ring = (i: number) => (t < 12.55 ? 0 : (((t - 12.55 - i * 0.4) % 1.5) + 1.5) % 1.5 / 1.5);
  return (
    <div style={{ position: "relative", width: 900, height: 700, transform: `translateY(${((1 - rise) * 160).toFixed(1)}px)`, opacity: rise }}>
      <div style={{ position: "absolute", left: 160, top: 40, width: 580, height: 580, transform: "rotateX(60deg) rotateZ(45deg)", transformStyle: "preserve-3d" }}>
        <div style={{ position: "absolute", inset: 0, transform: "translate(34px, 34px)", background: "radial-gradient(circle, rgba(29,42,18,0.55) 1.6px, transparent 2px) 0 0/9px 9px" }} />
        <div style={{ position: "absolute", inset: 0, background: "#2B5A1C", boxShadow: "10px 10px 0 #1C3A12, 20px 20px 0 #163010" }}>
          <div style={{ position: "absolute", inset: 0, background: "repeating-linear-gradient(90deg, rgba(255,255,255,0.06) 0 48px, rgba(0,0,0,0.06) 48px 96px)" }} />
          <svg width={580} height={580} viewBox="0 0 580 580" fill="none" stroke="rgba(255,255,255,0.75)" strokeWidth={3}>
            {[70, 140, 210].map((r) => <circle key={r} cx={290} cy={290} r={r} opacity={0.55} />)}
            {[0, 1, 2].map((i) => <circle key={i} cx={290} cy={290} r={20 + ring(i) * 250} opacity={(1 - ring(i)) * 0.8} />)}
            <circle cx={290} cy={290} r={16} fill="#0E1F09" stroke="none" />
            <circle cx={290 + (1 - ball) * 230} cy={290 + (1 - ball) * 170} r={12} fill={WHITE} stroke="none" opacity={ball >= 1 ? 0 : 1} />
          </svg>
        </div>
      </div>
      <div style={{ position: "absolute", left: 446, top: 120 }}>
        <div style={{ width: 4, height: 230, background: WHITE }} />
        <div style={{ position: "absolute", left: 4, top: 0, width: 76, height: 48, background: FLAG, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: SANS, fontWeight: 800, fontSize: 22, color: WHITE, transform: `skewY(${(Math.sin(t * 5) * 4).toFixed(2)}deg)`, transformOrigin: "left" }}>GB</div>
      </div>
    </div>
  );
};
const SD: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: LIME, perspective: 1700 }}>
    <BigNum n="05" c="rgba(29,42,18,0.07)" t={t} at={CUT.D} />
    <TopLabel n="05" t={t} at={CUT.D + 0.1} />
    <div style={{ position: "absolute", left: 0, right: 0, top: 640 }}>
      <Words t={t} size={62} color={INK} ws={[["do", 10.84], ["que", 10.94], ["o", 11.08], ["seu", 11.14], ["imóvel", 11.3]]} gap={0.2} mark={[4]} markColor={MAGENTA} markAt={11.35} />
      <Words t={t} size={62} color={INK} ws={[["precisa?", 11.7]]} />
    </div>
    <div style={{ position: "absolute", left: 90, top: 790 }}><Green t={t} /></div>
    <div style={{ position: "absolute", left: 0, right: 0, top: 1560 }}>
      <Words t={t} size={52} color={INK} ws={[["vamos", 12.75], ["cuidar", 13.0], ["juntos?", 13.25]]} gap={0.22} mark={[2]} markColor={MAGENTA} markAt={13.4} />
    </div>
    <div style={{ position: "absolute", right: 100, top: 400, width: 3, height: 1000, borderLeft: "3px dotted rgba(255,255,255,0.7)" }} />
    <div style={{ position: "absolute", right: 90, top: 400 + ((t - 10.75) * 140) % 1000, width: 24, height: 24, borderRadius: 24, background: WHITE, boxShadow: "0 0 0 3px rgba(29,42,18,0.25)" }} />
    <Leak t={t} side="top" />
    <Grain seed={14} o={0.1} />
  </AbsoluteFill>
);

// ───────── E · 15–18 · amostra 1: arquivo com a foto da sala (preto e vermelho) ─────────
const SE: React.FC<{ t: number }> = ({ t }) => {
  const card = k(t, 15.2, 0.5);
  const lens = pop(t, 16.0, 0.45);
  const lines: [W[], number[]][] = [
    [[["O", 15.1], ["HÓSPEDE", 15.48], ["CHEGOU", 16.0]], [2]],
    [[["E", 16.2], ["A", 16.36], ["CASA", 16.5], ["ESTAVA", 17.0]], []],
    [[["IMPECÁVEL", 17.4]], [0]],
  ];
  return (
    <AbsoluteFill style={{ background: DARK }}>
      <BigNum n="08" c="rgba(255,255,255,0.04)" t={t} at={CUT.E} font={COND} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 330, display: "flex", justifyContent: "center", ...blurIn(t, 15.1) }}>
        <div style={{ fontFamily: "monospace", fontWeight: 700, fontSize: 24, letterSpacing: "0.18em", color: RED, borderBottom: `3px solid ${RED}`, paddingBottom: 6 }}>ARQUIVO 01 · GB HOUSE &amp; CO</div>
      </div>
