// trocas como na referência
type Tr = "wipeW" | "lime" | "flashW" | "blur" | "cut" | "zoom" | "glitchO";
const SCENES: [number, React.FC<{ t: number }>, Tr][] = [
  [-9, SA, "cut"], [CUT.B, SB, "wipeW"], [CUT.C, SC, "lime"], [CUT.D, SD, "flashW"], [CUT.E, SE, "blur"], [CUT.F, SF, "zoom"],
  [CUT.G, SG, "blur"], [CUT.H, SH, "blur"], [CUT.I, SI, "blur"], [CUT.J, SJ, "cut"], [CUT.K, SK, "cut"], [CUT.L, SL, "blur"],
  [CUT.M, SM, "blur"], [CUT.N, SN, "glitchO"], [CUT.O, SO, "lime"],
];
const TD = 0.3;

export const GbHouseRef2: React.FC = () => {
  const t = useCurrentFrame() / GBR2_FPS;
  const i = SCENES.findIndex((s, j) => t >= s[0] && (j + 1 >= SCENES.length || t < SCENES[j + 1][0]));
  const [, S] = SCENES[Math.max(0, i)];
  let fx: React.CSSProperties = {};
  let over: React.ReactNode = null;
  for (let j = 1; j < SCENES.length; j++) {
    const c = SCENES[j][0], d = t - c;
    if (Math.abs(d) > TD) continue;
    const a = 1 - Math.abs(d) / TD;
    const kind = SCENES[j][2];
    if (kind === "wipeW") over = <AbsoluteFill style={{ background: `linear-gradient(90deg, rgba(253,253,253,0) 0%, ${WHITE} 40%, ${WHITE} 100%)`, transform: `translateX(${((d < 0 ? 1 - a : 0) * 100).toFixed(1)}%)`, opacity: d < 0 ? 1 : a }} />;
    if (kind === "lime") { over = <AbsoluteFill style={{ background: LIME, opacity: a * 0.85 }} />; fx = { filter: `blur(${(a * 12).toFixed(1)}px)` }; }
    if (kind === "flashW") { over = <AbsoluteFill style={{ background: WHITE, opacity: a * 0.95 }} />; fx = { filter: `blur(${(a * 14).toFixed(1)}px)`, transform: `scale(${(1 + 0.05 * a).toFixed(4)})` }; }
    if (kind === "blur") fx = { filter: `blur(${(a * 18).toFixed(1)}px) brightness(${(1 + 0.3 * a).toFixed(2)})`, transform: `scale(${(1 + 0.04 * a).toFixed(4)})` };
    if (kind === "zoom") fx = { filter: `blur(${(a * 8).toFixed(1)}px)`, transform: `scale(${(d < 0 ? 1 + 0.3 * a : 1 + 0.1 * a).toFixed(4)})` };
    if (kind === "glitchO") {
      fx = { filter: `blur(${(a * 6).toFixed(1)}px) contrast(${(1 + a * 0.6).toFixed(2)})`, transform: `translateX(${(Math.sin(t * 80) * 26 * a).toFixed(1)}px)` };
      over = <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(255,120,30,${(0.85 * a).toFixed(2)}) 0%, rgba(230,40,20,${(0.6 * a).toFixed(2)}) 50%, rgba(255,255,255,${(0.7 * a).toFixed(2)}) 100%)`, mixBlendMode: "screen" }} />;
    }
  }
  return (
    <AbsoluteFill style={{ background: "#000" }}>
      <AbsoluteFill style={fx}><S t={t} /></AbsoluteFill>
      {over}
    </AbsoluteFill>
  );
};

